protocol OrderPort { func place(_ order: Order) async throws -> Receipt }

struct LegacyOrderAdapter: OrderPort {
    let base: URL
    let session: URLSession                       // configuration lives here
    func place(_ order: Order) async throws -> Receipt {
        var req = URLRequest(url: base.appendingPathComponent("orders"))
        req.httpBody = try JSONEncoder().encode(LegacyOrderDTO(order))  // translate out
        let (data, resp) = try await session.data(for: req)
        guard let http = resp as? HTTPURLResponse,
              (200..<300).contains(http.statusCode) else {
            throw OrderRejected("legacy returned a non-success response")
        }
        return try Receipt(legacy: JSONDecoder().decode(LegacyReceiptDTO.self, from: data))
    }
}
